[TFMPageType('Search', "Search")]
class TFMPageSearchConfiguration extends TFMPageConfiguration
{
    TFMListId	listId;
    boolean			automaticAcceptOnOpen;
    boolean			hideAfterAccept;
    boolean			close;
    boolean         enabled;


}

Method.Source:
[TFMPageConfigurationAttributeAttribute(classStr(TFMListShortLookup),'list','',true)]
public TFMListId parmListId(TFMListId _listId = listId)
{
    TFMList			listCls;
    listId = _listId;
    if (className2Id(listId))
    {
        listCls = new SysDictClass(className2Id(listId)).makeObject();
        listId = listCls.parmListName();
    }
    return listId;
}

[TFMPageConfigurationAttributeAttribute(false,'header','',true)]
public boolean parmAutomaticAcceptOnOpen(boolean _automaticAcceptOnOpen = automaticAcceptOnOpen)
{
    automaticAcceptOnOpen = _automaticAcceptOnOpen;
    return automaticAcceptOnOpen;
}

[TFMPageConfigurationAttributeAttribute(true,'header','',true)]
public boolean parmHideAfterAccept(boolean _hideAfterAccept = hideAfterAccept)
{
    hideAfterAccept = _hideAfterAccept;
    return hideAfterAccept;
}

[TFMPageConfigurationAttributeAttribute(true,'onResultSelected', '', true)]
public boolean parmEnabled(boolean _enabled = enabled)
{
    enabled = _enabled;
    return enabled;
}

[TFMPageConfigurationAttributeAttribute(true,'onResultSelected', '', true)]
public boolean parmClose(boolean _close = close)
{
    close = _close;
    return close;
}
